<?php require 'config.php';auth();$p=db();$counts=['Clients'=>$p->query('SELECT COUNT(*) FROM clients')->fetchColumn(),'Projects'=>$p->query('SELECT COUNT(*) FROM projects')->fetchColumn(),'In progress'=>$p->query("SELECT COUNT(*) FROM projects WHERE status='In Progress'")->fetchColumn(),'New inquiries'=>$p->query("SELECT COUNT(*) FROM inquiries WHERE status='New'")->fetchColumn()];$projects=$p->query('SELECT p.*,c.name client FROM projects p LEFT JOIN clients c ON c.id=p.client_id ORDER BY p.created_at DESC LIMIT 6')->fetchAll();$page='Overview';require 'includes/header.php';?><div class="heading"><div><p class="eyebrow">YOUR BUSINESS AT A GLANCE</p><h1>Overview</h1><p class="muted">Welcome back, <?=e($_SESSION['username'])?>. Here's your workspace summary.</p></div><a class="btn primary" href="clients.php">＋ Manage clients</a></div><div class="metrics"><?php foreach($counts as $label=>$n):?><article class="metric"><span><?=e($label)?></span><strong><?=number_format((int)$n)?></strong><small>Live database records</small></article><?php endforeach;?></div><section class="panel"><div class="panel-head"><div><h2>Recent projects</h2><p>Latest project records</p></div><a href="projects.php">View all →</a></div><?php if(!$projects):?><div class="empty">No projects yet. Add a project from the Projects page.</div><?php else:?><div class="table-wrap"><table><thead><tr><th>Project</th><th>Client</th><th>Status</th><th>Budget (NGN)</th><th>Actions</th></tr></thead><tbody><?php foreach($projects as $r):?><tr><td><?=e($r['name'])?></td><td><?=e($r['client']??'—')?></td><td><span class="pill"><?=e($r['status'])?></span></td><td><?= $r['budget']!==null?'₦'.number_format((float)$r['budget'],2):'—'?></td><td><a href="projects.php?edit=<?=(int)$r['id']?>">Edit</a></td></tr><?php endforeach;?></tbody></table></div><?php endif;?></section><?php require 'includes/footer.php';?>
